package consumes

import (
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"

	"github.com/KogenAI/kogen-executor/executor/claudecode"
)

// fakeRuntime installs a synthetic runtime without downloading or running Claude Code.
func fakeRuntime(t testing.TB, home, version string) string {
	t.Helper()
	script := `#!/bin/sh
if [ "$1" = "--version" ]; then
  echo ` + shQuote(version) + `
  exit 0
fi
if [ "$1" = "auth" ] && [ "$2" = "status" ] && [ "$3" = "--json" ]; then
  echo '{"loggedIn":true,"authMethod":"claude.ai"}'
  exit 0
fi
exit 9
`
	p := claudecode.RuntimePath(home)
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil { t.Fatal(err) }
	if err := os.WriteFile(p, []byte(script), 0o755); err != nil { t.Fatal(err) }
	var size int64
	switch runtime.GOOS + "/" + runtime.GOARCH {
	case "darwin/arm64": size = 319598464
	case "linux/amd64": size = 337814032
	}
	if size != 0 { if err := os.Truncate(p, size); err != nil { t.Fatal(err) } }
	return p
}

func shQuote(s string) string { return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'" }

func mustJSON(t testing.TB, v any) string {
	t.Helper()
	b, err := json.Marshal(v)
	if err != nil { t.Fatal(err) }
	return string(b)
}

func writeJSON(t testing.TB, p string, v any) string {
	t.Helper()
	if err := os.WriteFile(p, []byte(mustJSON(t, v)), 0o600); err != nil { t.Fatal(err) }
	return p
}

func realDir(t testing.TB) string {
	t.Helper()
	dir, err := filepath.EvalSymlinks(t.TempDir())
	if err != nil { t.Fatal(err) }
	return dir
}

